                <th>Forma de Pagamento</th>
                <th>Código de rastreio</th>
                <th>Status Encomenda</th>
                <th>  </th>
              </tr>
            </thead>
            <tbody>{displayPurchases}</tbody>
            <tbody>{displayTotal}</tbody>
          </table>
          <ReactPaginate
            previousLabel={<FaChevronLeft />}
            nextLabel={<FaChevronRight />}
            pageCount={pageCount}
